const Fastify = require('./fastify')

async function run (tp, remoteAddress) {
  const app = Fastify({ trustProxy: tp })
  app.get('/', (req, reply) => reply.send({
    ip: req.ip,
    ips: req.ips,
    host: req.host,
    proto: req.protocol,
    hostname: req.hostname,
    port: req.port
  }))
  const res = await app.inject({
    method: 'GET',
    url: '/',
    headers: {
      'x-forwarded-for': '1.2.3.4',
      'x-forwarded-host': 'example.com',
      'x-forwarded-proto': 'https',
      host: 'localhost:3000'
    },
    remoteAddress
  })
  console.log(JSON.stringify(tp), JSON.stringify(remoteAddress), res.payload)
  await app.close()
}

