const http = require('node:http')
const os = require('node:os')
const path = require('node:path')

const socketPath = path.join(os.tmpdir(), `t-${process.pid}.sock`)
const server = http.createServer((req, res) => {
  console.log('remoteAddress:', JSON.stringify(req.socket.remoteAddress))
  res.end('ok')
})
